package com.digitalminds.angelina

/** Un ejemplo de ayuda: lo que se escribe, si requiere modo GRADOS y lo que responde Giac (comprobado en las pruebas). */
class HEx(val input: String, val out: String, val deg: Boolean = false)

/** Ayuda de una tecla: para qué sirve, cómo se usa, ejemplos con números y una nota. */
class KHelp(val title: String, val what: String, val how: String, val ex: List<HEx>, val note: String = "")

/** Generado a partir de la lista de ayudas; cada resultado lo calculó Giac 1.9 y lo vuelve a comprobar KeyHelpTest. */
object KeyHelp {
    val map: Map<String, KHelp> = HashMap<String, KHelp>().also { m -> part0(m); part1(m); part2(m); part3(m); part4(m); part5(m) }

    fun of(label: String): KHelp? = map[label]

    private fun part0(m: MutableMap<String, KHelp>) {
        m["sen"] = KHelp("Seno", "Razón entre el cateto opuesto y la hipotenusa de un ángulo.", "Pulsa sen, escribe el ángulo y pulsa =. Revisa arriba a la derecha si estás en GRADOS o RAD.", listOf(HEx("sin(30)", "1/2", true), HEx("sin(90)", "1", true)), "Truco CO CA CO CA HIP HIP: sen = CO/HIP, cos = CA/HIP, tan = CO/CA. En exámenes se usa sen 37° ≈ 3/5 (valor aproximado).")
        m["cos"] = KHelp("Coseno", "Razón entre el cateto adyacente y la hipotenusa.", "Pulsa cos, escribe el ángulo y pulsa =.", listOf(HEx("cos(60)", "1/2", true), HEx("cos(0)", "1", true)), "cos 53° ≈ 3/5 es un valor aproximado del triángulo 37° y 53°.")
        m["tan"] = KHelp("Tangente", "Razón entre el cateto opuesto y el adyacente.", "Pulsa tan, escribe el ángulo y pulsa =.", listOf(HEx("tan(45)", "1", true), HEx("tan(60)", "sqrt(3)", true)), "tan 90° no está definida; la app muestra infinito.")
        m["ln"] = KHelp("Logaritmo natural", "Logaritmo en base e (e ≈ 2,718).", "Pulsa ln, escribe el número positivo y pulsa =.", listOf(HEx("ln(1)", "0"), HEx("ln(exp(3))", "3")), "Solo existe para números mayores que 0.")
        m["log"] = KHelp("Logaritmo decimal", "Logaritmo en base 10: a qué potencia se eleva 10 para dar el número.", "Pulsa log, escribe el número y pulsa =.", listOf(HEx("log10(1000)", "3"), HEx("log10(0.01)", "-2.0")))
        m["√"] = KHelp("Raíz cuadrada", "Número que multiplicado por sí mismo da el radicando.", "Pulsa √ y escribe el número. Para salir de la raíz desliza a la derecha sobre la línea.", listOf(HEx("sqrt(144)", "12"), HEx("sqrt(12)", "2*sqrt(3)"), HEx("sqrt(3+2*sqrt(2))", "sqrt(2)+1")), "La app simplifica: √12 = 2√3.")
        m["x²"] = KHelp("Al cuadrado", "Multiplica un número por sí mismo.", "Escribe el número y pulsa x².", listOf(HEx("7^2", "49"), HEx("(2/3)^2", "4/9")))
