        m["π"] = KHelp("Número pi", "Razón entre la longitud de una circunferencia y su diámetro (≈ 3,1416).", "Pulsa π donde lo necesites.", listOf(HEx("pi*5^2", "pi*25"), HEx("evalf(pi)", "3.14159265359")), "π·5² es el área de un círculo de radio 5. Toca el resultado para verlo en decimal.")
        m["e"] = KHelp("Número e", "Base de los logaritmos naturales (≈ 2,71828).", "Pulsa e. Para eˣ mantén pulsada la tecla o desliza hacia arriba.", listOf(HEx("ln(exp(1))", "1")))
        m["sen⁻¹"] = KHelp("Arco seno", "Ángulo cuyo seno es el número dado.", "Pulsa sen⁻¹, escribe un valor entre −1 y 1 y pulsa =.", listOf(HEx("asin(1/2)", "30", true), HEx("asin(1)", "90", true)), "En modo GRADOS el resultado sale en grados.")
        m["cos⁻¹"] = KHelp("Arco coseno", "Ángulo cuyo coseno es el número dado.", "Pulsa cos⁻¹, escribe un valor entre −1 y 1 y pulsa =.", listOf(HEx("acos(1/2)", "60", true), HEx("acos(0)", "90", true)))
