        m["tanh⁻¹"] = KHelp("Tangente hiperbólica inversa", "Número cuya tangente hiperbólica es el dado (entre −1 y 1).", "Pulsa tanh⁻¹ y escribe el número.", listOf(HEx("atanh(3/5)", "ln(4)/2")))
        m["eˣ"] = KHelp("Exponencial", "Eleva e a un exponente.", "Pulsa eˣ y escribe el exponente.", listOf(HEx("exp(0)", "1"), HEx("exp(ln(5))", "5")))
