    private fun part2(m: MutableMap<String, KHelp>) {
        m["p.dec"] = KHelp("Parte decimal", "Lo que queda después de la coma.", "Pulsa p.dec y escribe el número.", listOf(HEx("fPart(3.75)", "0.75")))
